const sourceTitle={B:'基础讲义',E:'强化讲义',H:'强化习题'};
const icon=(name,size=16)=>({
 arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',back:'<path d="m12 19-7-7 7-7m-7 7h14"/>',search:'<circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/>',plus:'<path d="M12 5v14M5 12h14"/>',fit:'<path d="M8 3H4v4m12-4h4v4M4 16v4h4m12-4v4h-4"/>',edit:'<path d="m15 5 4 4m-13 9 3-.5L19 7l-3-3L5.5 14.5 5 18z"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M5 21h14"/>',upload:'<path d="M12 18V5m-5 5 5-5 5 5M5 21h14"/>',check:'<path d="m5 12 4 4L19 6"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 9a8 8 0 0 1 14-2l1 5M4 12l1 5a8 8 0 0 0 14-2"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',trash:'<path d="M5 7h14m-2 0-1 14H8L7 7m3 0V4h4v3"/>',chevron:'<path d="m9 18 6-6-6-6"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z"/>',undo:'<path d="M9 14 4 9l5-5M4 9h10a6 6 0 0 1 0 12"/>',redo:'<path d="m15 14 5-5-5-5m5 5H10a6 6 0 0 0 0 12"/>'}[name]||'');
const svg=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon(name)}</svg>`;
let progress={}, edits={}, gameHistory={}, expanded=new Set(), selectedNode=null, camera={x:0,y:0,z:.75}, activeMap=null, answerReveal={},routeInfo=null, currentMode='free',game=null, questionListShown=12;
const getStored=(key,defaultValue)=>{try{return JSON.parse(localStorage.getItem(key))??defaultValue}catch{return defaultValue}};
progress=getStored('snow_atlas_progress',{});edits=getStored('snow_atlas_edits',{});gameHistory=getStored('snow_atlas_games',{});
expanded=new Set(getStored('snow_atlas_expanded',[]));
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch(err){toast('存储空间可能已满，请先导出备份。')}};
const saveProgress=()=>save('snow_atlas_progress',progress);
const saveEdits=()=>save('snow_atlas_edits',edits);
const saveGame=()=>save('snow_atlas_games',gameHistory);
const tap=()=>{try{navigator.vibrate?.(10)}catch{}};
document.addEventListener('pointerdown',e=>{if(e.target.closest('button,.entry-row,.chapter-line,.launch-primary,.launch-secondary,.choice-card,.primary-nav a'))tap()},{passive:true});
 document.addEventListener('pointerdown',e=>{const b=e.target.closest('.btn,.choice-card,.game-mode,.soft-btn,.icon-square');if(!b||b.disabled)return;const r=b.getBoundingClientRect(),dot=document.createElement('span');dot.className='press-ripple';dot.style.left=(e.clientX-r.left)+'px';dot.style.top=(e.clientY-r.top)+'px';b.appendChild(dot);setTimeout(()=>dot.remove(),550)},{passive:true});
let toastId;function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>el.classList.remove('show'),2800)}
const cardTitle=(title)=>esc(title||'');
function route(){const raw=(location.hash||'#/home').replace(/^#\/?/,'').split('/').filter(Boolean);return{page:raw[0]||'home',id:decodeURIComponent(raw[1]||'')}}
function setNav(page){$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page))}
function switchRoute(){closeModal();if(activeMap){activeMap.cleanup();activeMap=null;}routeInfo=route();const {page,id}=routeInfo;setNav(['problem','method'].includes(page)?(page==='problem'?'problems':'atlas'):page);const app=$('#app');app.className='page-'+page;
 if(page==='home')renderHome(app);
 else if(page==='atlas')renderMap(app);
 else if(page==='problems')renderProblems(app);
 else if(page==='problem')renderProblem(app,id);
 else if(page==='method')renderMethod(app,id);
 else if(page==='practice')renderPractice(app,id);
 else if(page==='review')renderReview(app);
 else{location.hash='#/home';return;}
 if(page!=='atlas')window.scrollTo({top:0,behavior:'instant'});
}
function moduleCount(mid){return D.nodes.filter(n=>n.module===mid).length}
const artFiles=['assets/monet-snow.jpg','assets/vangogh-orchard.webp','assets/monet-cliff.jpg','assets/vangogh-roses.jpg','assets/monet-river.jpg'];
function artRibbon(i=0){return `<div class="study-art-ribbon" aria-hidden="true"><img src="${artFiles[i%artFiles.length]}" alt=""></div>`}
function renderHome(app){const sample=D.exercises.find(e=>progress['ex:'+e.id]?.status==='reviewing')||D.exercises[0];
app.innerHTML=`<div class="atelier-home"><section class="atelier-hero"><div class="atelier-copy"><h1>一纸之间，<br>万千路径。</h1><p>曲线与曲面积分 · 数学书房</p><div class="atelier-stats"><span><b>${D.modules.length}</b> 章节</span><span><b>${D.nodes.length}</b> 方法</span><span><b>${D.exercises.length}</b> 题目</span></div><a href="#/atlas">展开知识的脉络 ↗</a></div><figure class="atelier-paint"><img src="assets/monet-cliff.jpg" alt="莫奈笔下的海岸"><img class="atelier-inset" src="assets/vangogh-roses.jpg" alt="梵高笔下的玫瑰"></figure></section><section class="atelier-entries"><a href="#/atlas"><h2>知识的脉络</h2><p>沿着章节，展开方法之间的联系。</p><span>↗</span></a><a href="#/practice"><h2>解题的直觉</h2><p>判断题型、核对条件、选择通法。</p><span>↗</span></a><a href="#/problem/${sample.id}"><h2>纸上的推演</h2><p>从一道题出发，读懂每一步。</p><span>↗</span></a></section><section class="atelier-contents"><figure><img src="assets/monet-river.jpg" alt="莫奈笔下的河岸" loading="lazy"></figure><div><h2>积分手记</h2><div class="chapter-index">${D.modules.map(m=>`<a class="chapter-line" href="#/atlas?module=${encodeURIComponent(m.id)}"><strong>${esc(m.title)}</strong><span>${moduleCount(m.id)} 个方法 ↗</span></a>`).join('')}</div></div></section><section class="atelier-gallery"><img src="assets/vangogh-orchard.webp" alt="盛开的果园" loading="lazy"><div><span>∫</span><p>让思考落在纸上。</p><a href="#/review">翻阅学习记录 ↗</a></div><img src="assets/monet-snow.jpg" alt="雪中的麦垛" loading="lazy"></section></div>`;}
function exerciseTile(e){return `<a class="problem-tile" href="#/problem/${encodeURIComponent(e.id)}"><div class="tile-meta"><span class="id">${esc(e.id)}</span><span>${esc(sourceTitle[e.source])} · ${esc(e.label)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.method)}</p><div style="margin-top:13px"><span class="tag">${esc(moduleTitle(e.module))}</span>${progress['ex:'+e.id]?.status==='mastered'?'<span class="tag warm">已掌握</span>':''}</div><span class="tile-arrow">↗</span></a>`}
function renderProblems(app){app.innerHTML=`${artRibbon(2)}<div class="page-container"><div class="page-hero"><span class="eyebrow">题库 / 74 道题</span><h1>题库<span style="color:#a8b7c5">.</span></h1><p>按来源和章节查找题目。</p></div><div class="filters-bar"><input class="filter-input" id="problem-search" type="search" placeholder="搜索题号、题型、方法或关键字……" aria-label="搜索题目"/><select class="filter-select" id="problem-source"><option value="">全部来源</option>${['B','E','H'].map(x=>`<option value="${x}">${sourceTitle[x]}</option>`).join('')}</select><select class="filter-select" id="problem-module"><option value="">全部知识章节</option>${D.modules.map(m=>`<option value="${m.id}">${esc(m.title)}</option>`).join('')}</select></div><div class="results-meta"><span id="problem-result-count"></span><a class="text-link" href="#/practice">只练方法，不做计算 ↗</a></div><div id="problem-results" class="problem-grid"></div><div id="load-wrap" style="text-align:center;margin-top:23px"></div></div>`;
 function update(reset=true){if(reset)questionListShown=12;const q=$('#problem-search')?.value.trim().toLowerCase()||'',src=$('#problem-source')?.value||'',mod=$('#problem-module')?.value||'';
 const list=D.exercises.filter(e=>(!q||[e.id,e.title,e.method,moduleTitle(e.module),e.label,sourceTitle[e.source]].some(s=>String(s).toLowerCase().includes(q)))&&(!src||e.source===src)&&(!mod||e.module===mod));
 $('#problem-result-count').textContent=`已收录 ${D.exercises.length} 道 · 当前显示 ${Math.min(questionListShown,list.length)} / ${list.length} 道`;
 $('#problem-results').innerHTML=list.length?list.slice(0,questionListShown).map(exerciseTile).join(''):'<div class="empty-state" style="grid-column:1/-1"><strong>暂未找到匹配题目</strong>试试更短的关键词，或清空筛选条件。</div>';
 $('#load-wrap').innerHTML=questionListShown<list.length?'<button class="btn btn-outline" id="load-more">继续浏览题目 ↓</button>':'';
 $('#load-more')?.addEventListener('click',()=>{questionListShown+=12;update(false);});}
 ['problem-search','problem-source','problem-module'].forEach(id=>$('#'+id).addEventListener(id==='problem-search'?'input':'change',()=>update()));update();}
function currentProblemNav(id){let i=D.exercises.findIndex(x=>x.id===id);return{prev:D.exercises[i-1],next:D.exercises[i+1]}}
function solutionSteps(content){const tmp=document.createElement('div');tmp.innerHTML=content;let groups=[],cur=[];Array.from(tmp.childNodes).forEach(node=>{if(node.nodeType===1&&node.tagName==='H4'&&cur.length){groups.push(cur.map(x=>x.outerHTML||x.textContent).join(''));cur=[]}cur.push(node)});if(cur.length)groups.push(cur.map(x=>x.outerHTML||x.textContent).join(''));return groups.length?groups:[content]}
function renderProblem(app,id){const e=byId(id);if(!e){app.innerHTML='<div class="page-container"><h1>没有找到这道题</h1><a href="#/problems">返回题库</a></div>';return;}
 const {prev,next}=currentProblemNav(id);const reveal=answerReveal[id]??0;const steps=solutionSteps(e.solutionHtml);const p=progress['ex:'+id]||{};
 app.innerHTML=`${artRibbon(0)}<div class="page-container reading-page"><div class="reading-back"><a href="#/problems">${svg('back')} 返回题库</a><span>${esc(moduleTitle(e.module))} / ${esc(e.id)}</span></div><div class="reading-header"><div class="reading-eyebrow"><span>${esc(sourceTitle[e.source])} · ${esc(e.label)}</span><i class="dot"></i><span>数学一 · ${esc(moduleTitle(e.module))}</span></div><h1>${esc(e.title)}</h1><div><span class="tag">${esc(e.id)}</span><span class="tag">完整解析 · ${steps.length} 段</span>${e.diagramType==='redrawn'?'<span class="tag">重绘图解</span>':''}</div></div>
 <a class="problem-method-cta" href="#/practice/${e.id}">先练方法判断　↗</a><div class="reading-shell"><div class="reading-main"><article class="reading-card"><div class="card-kicker"><span>01 / 题干</span><span>原题</span></div><div class="math-content">${cleanQuestionMarkup(e.questionHtml)}</div>${e.figureImages?.length?`<div class="source-figs">${e.figureImages.map((src,i)=>`<figure class="diagram-frame"><img loading="lazy" class="zoomable" src="${esc(src)}" alt="${esc(e.title)}配图 ${i+1}"/><figcaption>${esc(e.figureCaptions?.[i]||'配图 · 点击放大')}</figcaption></figure>`).join('')}</div>`:''}</article>
 ${e.correction?`<aside class="reading-card" style="border-color:#ddc7b9;background:#fffaf5;padding:21px 26px"><div class="card-kicker">原资料核对</div><div style="font:13px/2 var(--serif);color:#9b726a">${esc(e.correction)}</div></aside>`:''}
 <article class="reading-card"><div class="reading-steps-head"><div><span class="eyebrow">02 / 解析</span><h2>正规解析 · 一步一步来</h2><p>可以逐步揭晓，也可以直接阅读完整解答。</p></div><button class="soft-btn" id="full-answer">${reveal>=steps.length?'收起解析':'查看完整解析'}</button></div><div id="answer-body" class="math-content solution-content">${reveal===0?'<div class="answer-placeholder">解析暂时折起。试着先写出这道题的第一步。</div>':steps.slice(0,reveal).map(x=>`<div class="step-block">${x}</div>`).join('')}</div><div class="answer-actions"><button class="btn btn-primary" id="next-answer" ${reveal>=steps.length?'disabled':''}>${reveal?'继续揭晓下一步':'揭晓第一步'} ${svg('chevron')}</button><button class="btn btn-outline" id="answer-collapse">重新收起</button></div></article>
 ${e.answerImages?.length?`<details class="reading-card" style="padding:24px"><summary style="cursor:pointer;font:15px var(--serif);color:#718991">查看原资料参考图（${e.answerImages.length} 张）</summary><div class="source-figs" style="margin-top:24px">${e.answerImages.map((src,i)=>`<div class="diagram-frame"><img loading="lazy" class="zoomable" src="${esc(src)}" alt="参考资料截图 ${i+1}"/></div>`).join('')}</div></details>`:''}
 <article class="reading-card" style="padding:26px"><div class="card-kicker">03 / 知识关联</div><h2 style="font:500 20px var(--serif)">这道题连接的知识</h2><div class="related-inline">${(e.nodeIds||[]).map(nid=>`<a href="#/method/${encodeURIComponent(nid)}">${esc(nodeById(nid)?.title||nid)} ↗</a>`).join('')||`<a href="#/atlas">查看知识图谱 ↗</a>`}</div><div class="paper-ribbon"></div><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap">${prev?`<a class="btn btn-outline btn-sm" href="#/problem/${prev.id}">← ${esc(prev.id)} 上一题</a>`:'<span></span>'}${next?`<a class="btn btn-outline btn-sm" href="#/problem/${next.id}">下一题 ${esc(next.id)} →</a>`:''}</div></article>
 </div><aside class="reading-rail"><div class="rail-card"><h3>学习路径</h3><p>先审题，再找方法。不要让完整答案替你做判断。</p><div class="rail-step active"><span>1</span>辨认类型与条件</div><div class="rail-step"><span>2</span>选择关键第一步</div><div class="rail-step"><span>3</span>完整推导与核查</div><a class="btn btn-primary btn-sm rail-btn" href="#/practice/${e.id}">方法识别试炼 ${svg('chevron')}</a></div><div class="rail-card"><h3>掌握记录</h3><p>不靠看懂判断掌握，最好独立完成第一步列式。</p><button class="btn ${p.status==='mastered'?'btn-primary':'btn-outline'} btn-sm rail-btn" id="mark-mastered">${p.status==='mastered'?'✓ 已掌握':'标记已掌握'}</button><button class="btn ${p.status==='reviewing'?'btn-primary':'btn-outline'} btn-sm rail-btn" id="mark-reviewing">${p.status==='reviewing'?'↺ 待复盘':'加入待复盘'}</button></div><div class="rail-card"><h3>方法线索</h3><p>${esc(e.method)}</p></div></aside></div></div>`;
 function revealTo(n){answerReveal[id]=n;const body=$('#answer-body');if(!body)return;body.innerHTML=n===0?'<div class="answer-placeholder">解析暂时折起。试着先写出这道题的第一步。</div>':steps.slice(0,n).map(x=>`<div class="step-block">${x}</div>`).join('');$('#next-answer').disabled=n>=steps.length;$('#next-answer').innerHTML=`${n?'继续揭晓下一步':'揭晓第一步'} ${svg('chevron')}`;$('#full-answer').textContent=n>=steps.length?'收起解析':'查看完整解析';}
 $('#next-answer').onclick=()=>{tap();revealTo(Math.min(steps.length,(answerReveal[id]||0)+1));};$('#full-answer').onclick=()=>{tap();revealTo((answerReveal[id]||0)>=steps.length?0:steps.length)};$('#answer-collapse').onclick=()=>revealTo(0);
 ['mastered','reviewing'].forEach(stat=>$('#mark-'+stat).onclick=()=>{progress['ex:'+id]={...progress['ex:'+id],status:stat,updated:Date.now()};saveProgress();toast(stat==='mastered'?'已标记为掌握':'已加入待复盘');switchRoute();});
 attachZoomImages(app);
}
function attachZoomImages(root){$$('.zoomable',root).forEach(img=>img.addEventListener('click',()=>{openModal(`<div class="modal-panel image-modal"><div class="modal-head"><h2>放大查看配图</h2><button class="modal-close" data-close-modal aria-label="关闭">×</button></div><img src="${esc(img.currentSrc||img.src)}" alt="${esc(img.alt)}"/></div>`)}))}
function renderMethod(app,id){const n=nodeById(id)||edits.custom?.find(x=>x.id===id);if(!n){app.innerHTML='<div class="method-page">找不到此方法。<a href="#/atlas">返回图谱</a></div>';return;}
 const title=edits.nodes?.[id]?.title||n.title;const related=n.exerciseIds||[];const extra=edits.nodes?.[id]?.note||n.note||'';
 app.innerHTML=`${artRibbon(4)}<div class="method-page"><div class="reading-back"><a href="#/atlas">${svg('back')} 返回无边图谱</a><span>${esc(moduleTitle(n.module))}</span></div><div class="reading-header"><div class="eyebrow">方法 / ${esc(moduleTitle(n.module))}</div><h1>${esc(title)}</h1><p style="font:13px/1.9 var(--serif);color:#879c9f">方法、原理与例题，一起理解。你也可以在无限图谱上补充自己的笔记。</p></div><article class="reading-card"><div class="card-kicker">知识讲解</div><div class="math-content solution-content">${n.html||'<p>这是你添加的新节点。可以在导图里编辑备注，建立自己的方法体系。</p>'}</div>${extra?`<div class="paper-ribbon"></div><h3 class="serif">我的补充</h3><p class="serif" style="white-space:pre-wrap;color:#68808b">${esc(extra)}</p>`:''}</article><article class="reading-card"><div class="card-kicker">对应练习</div><h2 style="font:500 23px var(--serif);margin:0 0 19px">对应题目</h2>${related.length?`<div class="problem-grid">${related.slice(0,12).map(id=>byId(id)).filter(Boolean).map(exerciseTile).join('')}</div>`:'<p class="muted">暂未绑定题目。你可以在图谱中编辑节点添加题号。</p>'}<div class="method-nav"><a href="#/atlas" class="btn btn-outline btn-sm">${svg('back')} 回到图谱</a><button id="method-edit" class="btn btn-outline btn-sm">${svg('edit')} 编辑我的笔记</button></div></article></div>`;
 $('#method-edit').onclick=()=>editNode(id);}
/* Rule-based method training: 74 separately mapped exercises, five reasoning layers. */
 const routeOf={"B1":"curve_algebra","B2":"curve_param","B3":"curve_sym","B4":"line_param","B5":"line_tangent","B6":"work_vector","B7":"green_close","B8":"green_hole","B9":"path_test","B10":"path_potential","B11":"path_potential","B12":"surface_mass","B13":"surface_split","B14":"surface_cancel","B15":"gauss_direct","B16":"gauss_hole","B17":"vector_div","B18":"stokes_plane","B19":"vector_curl","E3":"curve_sym","E4":"curve_sym","E5":"line_split","E6":"line_exact","E7":"green_sym","E8":"path_closed","E9":"green_curl","E10":"surface_project","E11":"surface_project","E12":"surface_projection_flux","E13":"surface_cancel","E14":"surface_odd","E15":"gauss_centroid","E16":"gauss_limit","E17":"stokes_close","E18":"surface_mass","E19":"work_exact","H01":"volume_sym","H02":"volume_limit","H03":"volume_cyl","H04":"volume_unknown","H05":"volume_slice","H06":"curve_param","H07":"curve_param","H08":"curve_param","H09":"curve_sym","H10":"line_split","H11":"line_exact","H12":"line_reduce","H13":"line_sym","H14":"green_opt","H15":"green_exact","H16":"green_param","H17":"path_potential","H18":"path_ode","H19":"surface_project","H20":"surface_sym","H21":"surface_param","H22":"surface_project","H23":"surface_direction","H24":"surface_projection_flux","H25":"surface_odd","H26":"surface_projection_flux","H27":"surface_projection_flux","H28":"gauss_div","H29":"gauss_complete","H30":"gauss_complete","H31":"gauss_direct","H32":"stokes_surface","H33":"stokes_plane","H34":"surface_mass","H35":"volume_centroid","H36":"volume_centroid","H37":"volume_centroid","H38":"work_optim"};
 const conceptBank={"curve_algebra":{"family":"curve","route":"先利用曲线上恒等式化简被积式，再处理弧长","gate":"给定曲线方程能否把被积式化为常数或更简单的量","why":"沿曲线积分只取曲线上的函数值；代入约束可先消去难算项","pitfall":"未经化简就硬算复杂弧长或周长"},"curve_param":{"family":"curve","route":"选一个能完整覆盖弧段的参数，代入弧长微元","gate":"参数区间、曲线分支与弧长因子是否匹配","why":"第一类曲线积分需用非负弧长微元，反向不变号","pitfall":"把负支换成正支，或误把弧长微元写成有向微元"},"curve_sym":{"family":"curve","route":"先检验积分路径和被积式的对称性，轮换或配对消项","gate":"被积函数和曲线是否对同一个变换满足相应关系","why":"对称变换配对可令奇部积分抵消，或把多个积分化为相同量","pitfall":"只看曲线形状对称，却不检查被积式怎样变换"},"line_param":{"family":"line","route":"把曲线参数化，同时替换有向微分与上下限","gate":"参数必须沿题目指定方向从起点走到终点","why":"第二类曲线积分由有向微分决定符号；参数走向必须与路径一致","pitfall":"仅用坐标值大小定上下限，忽略路径实际行进方向"},"line_tangent":{"family":"line","route":"利用单位切向量，把有向微分写成切向分量乘弧长","gate":"曲线的圆心、弧段和切向量方向是否正确","why":"有向微分等于单位切向量分量乘弧长微元","pitfall":"把移动方向反了，或将偏心圆误作原点圆"},"line_split":{"family":"line","route":"按绝对值、分支或转折点分段参数化，必要时再比较格林公式","gate":"被积函数或参数表示在哪些分界点发生变化","why":"分段保证每段参数式和符号固定，同时可保持正确的有向积分","pitfall":"跨越分界点后仍使用同一符号或忽略方向"},"line_exact":{"family":"line","route":"先分离全微分项，其余部分再用参数或定理计算","gate":"哪一部分能写成某个标量函数的全微分","why":"全微分沿路径积分只与端点有关，复杂积分因而分解","pitfall":"把非全微分部分也直接当端点差，或错用闭路结果"},"line_reduce":{"family":"line","route":"先用约束化简空间曲线，再拆出零贡献和易算项","gate":"两曲面的交线是否可化成平面曲线或固定坐标","why":"在路径上成立的几何等式可直接代回有向积分","pitfall":"不先看交线关系，就将三个变量分别硬参数化"},"line_sym":{"family":"line","route":"根据有向曲线对称性配对，并保留方向符号","gate":"积分项在对称路径上的符号及有向元素如何变化","why":"同一路径的对称配对可消项，但有向微分仍受走向控制","pitfall":"把第一类积分的无向对称结论照搬到第二类"},"work_vector":{"family":"line","route":"先由大小与方向求力的坐标分量，再列做功积分","gate":"单位方向向量与题设夹角符号是否吻合","why":"力的大小乘单位方向才是力场；做功沿实际位移点乘","pitfall":"只写力大小，不写方向分量就直接积分"},"work_exact":{"family":"line","route":"判断是否为保守力，若存在势函数则用端点差","gate":"力的表达式是否能写成某个势函数的全微分","why":"保守力沿路径做功不依赖路径形状，势函数端点差即可","pitfall":"还没证明可写全微分，就跳过路径直接算端点差"},"green_close":{"family":"green","route":"补辅助边界形成闭曲线，用格林后减掉补线积分","gate":"原路径是否闭合，以及新增边界的正向是否一致","why":"格林公式把平面闭曲线积分转成区域二重积分","pitfall":"补线后忘记扣除辅助边界，或沿错方向"},"green_hole":{"family":"green","route":"从区域内剔除奇点，挖洞后对多连通区域用格林","gate":"向量场是否在整个被积区域内具有所需光滑性","why":"奇点会破坏直接套格林的前提；挖洞把不可用区域排除","pitfall":"区域含奇点仍直接使用格林公式"},"green_sym":{"family":"green","route":"先用格林转为面积积分，再通过变量交换或对称性化简","gate":"区域与被积式在变量交换下如何变化","why":"变换后的两个积分可合并、平均或比较以减少计算","pitfall":"只靠区域对称就认定所有积分项相等"},"green_curl":{"family":"green","route":"先把法向量表达转成有向切向积分，再考虑格林","gate":"切向与法向的取向关系是否正确","why":"平面法向与切向的旋转关系，连接了两种边界积分写法","pitfall":"忽略法向和边界正向的匹配"},"green_opt":{"family":"green","route":"用格林把闭路积分改写为区域有符号积分，按正负区域选边界","gate":"平面被积函数在不同区域是正还是负","why":"选取正贡献区域、排除负贡献区域，才能判定极值边界","pitfall":"看到闭合曲线就只算值，不分析被积函数的正负"},"green_exact":{"family":"green","route":"先剥离全微分，再对剩余闭路积分用格林","gate":"哪些项是全微分，哪些项需格林转换","why":"闭路全微分积分为零，使真正需要处理的部分更少","pitfall":"闭路全微分项与非全微分项混淆"},"green_param":{"family":"green","route":"引入缩放参数建立求导恒等式，再结合格林公式","gate":"缩放后的表达是否满足所需可导条件","why":"参数求导与区域积分的关系可建立欧拉型恒等式","pitfall":"未检查可导条件就对含参积分随意求导"},"path_test":{"family":"path","route":"先检验区域内偏导关系，再据路径无关条件判断","gate":"积分区域是否单连通且相关偏导连续","why":"在适当区域内，偏导相等可保证存在势函数","pitfall":"只检验偏导相等，完全忽略区域中的洞或奇点"},"path_potential":{"family":"path","route":"由一个分量积分恢复势函数，再用另一个分量确定补充函数","gate":"区域条件、积分分量与待定函数是否相互一致","why":"若微分式为全微分，则积分为势函数的终点减起点","pitfall":"求原函数漏掉只依赖其他变量的待定函数"},"path_closed":{"family":"path","route":"把两条路径拼成闭合边界，再利用闭路积分为零导出约束","gate":"拼接时两条路径的起终点和反向符号是否正确","why":"两路径积分相减是闭路积分，进而建立关于未知函数的关系","pitfall":"两条路径首尾不闭合或反向时漏负号"},"path_ode":{"family":"path","route":"由偏导一致关系建立常微分方程，再结合初值确定未知函数","gate":"偏导相等恒等式能否化为一元未知函数的方程","why":"路径无关条件可把多元关系转化成一元微分方程","pitfall":"只写偏导相等，不代初值确定完整解"},"surface_mass":{"family":"surfaceArea","route":"按面积元积分建立质量或一阶矩，利用对称性处理密度","gate":"研究对象是曲面薄壳而非实体，密度的奇偶部分如何处理","why":"薄壳质量使用面积元；重心是一阶矩除以质量","pitfall":"把面壳错当实体使用体积微元"},"surface_project":{"family":"surfaceArea","route":"选便于处理的投影或隐函数表达，写出正确面积因子","gate":"投影区域、曲面分支与面积元是否对应","why":"面积元在投影下需乘相应伸缩因子","pitfall":"直接以投影面积替代曲面面积，漏掉面积因子"},"surface_sym":{"family":"surfaceArea","route":"先利用曲面与密度对称性，把积分配对或轮换","gate":"曲面及被积函数是否对变量交换都满足相应关系","why":"对称配对和曲面约束可把多项积分化为简单量","pitfall":"仅凭曲面对称就认定密度也对称"},"surface_param":{"family":"surfaceArea","route":"选择柱面或旋转曲面的自然参数并计算面积元","gate":"简单平面投影是否退化，以及参数能否覆盖整个曲面","why":"自然参数化可避免退化投影并直接得到面积因子","pitfall":"把柱面投到不合适的平面并当作普通圆盘"},"surface_direction":{"family":"surfaceArea","route":"先确定单位方向或梯度，再用曲面面积元积分","gate":"题设方向量是否已经单位化","why":"最大方向由梯度确定，曲面积分仍需正确的面积元","pitfall":"把未经单位化的方向向量直接作为方向余弦"},"surface_projection_flux":{"family":"flux","route":"按指定侧的法向符号，把通量合成一次平面投影积分","gate":"上侧下侧、曲面表达和投影区域是否已经明确","why":"有向面积微元合一后可将通量转为平面二重积分","pitfall":"只写投影面积，不考虑法向方向或偏导符号"},"surface_cancel":{"family":"flux","route":"先写法向量与向量场的点乘，观察抽象项能否消去","gate":"抽象函数的系数与法向分量是否存在代数抵消","why":"通量由法向点乘决定，抽象项可能不用求导便消失","pitfall":"只知道抽象函数连续却擅自对它求导"},"surface_odd":{"family":"flux","route":"先固定曲面方向，再判断通量被积式的奇偶性","gate":"被积式与完整投影区域是否关于同一变量对称","why":"奇函数在对称区域积分为零，但法向符号必须先确定","pitfall":"漏掉上下侧引入的负号，或误判奇偶性"},"surface_split":{"family":"flux","route":"把曲面分成侧面与底面，分别选正确法向积分","gate":"曲面是否完整封闭，以及内部是否存在奇点","why":"分片计算兼顾各面取向；有奇点时不能直接套高斯","pitfall":"没有核对内部光滑条件就对拼合曲面套高斯"},"gauss_direct":{"family":"flux","route":"先在原曲面代入约束，比较直接投影与高斯哪条更短","gate":"原曲面约束能否把分母或通量表达化简","why":"定理不是唯一最优路径；直接化简往往更省计算","pitfall":"见到闭曲面就机械使用高斯，忽略原被积式简化"},"gauss_hole":{"family":"flux","route":"排除奇点挖去小球，再对余下闭合区域应用高斯","gate":"奇点是否位于封闭曲面的内部","why":"挖洞后定理在剩余光滑区域适用，内边界方向与外边界相反","pitfall":"把原点奇点当作不存在，直接按零散度算通量"},"gauss_centroid":{"family":"flux","route":"高斯转体积分后，用对称或形心求一阶矩","gate":"散度是否化为常数或坐标的一次式","why":"高斯公式连接通量与散度，体积分可用对称及形心简化","pitfall":"只计算体积不计算需要的一阶矩"},"gauss_limit":{"family":"flux","route":"先核查题目光滑前提，条件不足时不能无条件使用高斯","gate":"向量场是否在整个闭合区域及边界满足连续可导","why":"微分定理的前提是结论成立的必要条件，不能被形式计算取代","pitfall":"在定义或光滑性不足的点直接求散度"},"gauss_div":{"family":"flux","route":"核对闭合曲面与外侧后，计算散度化成三重积分","gate":"各边界面的取向是否统一为外侧","why":"高斯公式把闭合曲面的总通量变成内部散度的体积分","pitfall":"把单一开放曲面当闭曲面，或将内侧当外侧"},"gauss_complete":{"family":"flux","route":"先补平面面片形成闭曲面，高斯后扣除补面通量","gate":"补面的位置、法向和其自身积分能否简化","why":"添加辅助面后得到闭曲面，原通量等于总通量减辅助通量","pitfall":"补面后忘减其通量，或把补面法向方向弄反"},"stokes_plane":{"family":"line","route":"选同边界的简单平面片，利用斯托克斯转旋度通量","gate":"新曲面的边界和原曲线方向是否匹配右手规则","why":"斯托克斯允许换任意同边界的光滑定向曲面","pitfall":"只保留边界形状，忽略法向与右手规则"},"stokes_close":{"family":"line","route":"先补线使路径闭合，定向后再选曲面用斯托克斯","gate":"补线的行进方向与所选法向是否一致","why":"补线闭合路径后使用斯托克斯，再扣除补线贡献","pitfall":"补线后未扣除，或者补线与边界方向相反"},"stokes_surface":{"family":"line","route":"在同边界曲面中比较球面片与平面片，选旋度通量更简者","gate":"边界空间曲线与曲面方向是否一致","why":"换面不改变合条件的有向边界积分值","pitfall":"曲面法向和边界正向不符合右手规则"},"volume_sym":{"family":"volume","route":"利用球体轮换对称先化简，再考虑坐标积分","gate":"积分区域与被积式是否允许变量轮换","why":"旋转或轮换对称下同类平方项积分相等","pitfall":"只凭球面形状就将非对称的被积式任意替换"},"volume_limit":{"family":"volume","route":"用连续性把小球积分和球体积联系起来，再求极限","gate":"归一化分母是否等于实际球体积","why":"连续函数在收缩区域的平均值趋于中心值，但须保留体积系数","pitfall":"把题目给定的分母误当成球体体积"},"volume_cyl":{"family":"volume","route":"画投影区域，选极坐标或柱坐标写三重积分限","gate":"曲面、平面交线在极坐标下对应哪段角度与半径","why":"柱坐标把平面曲线与高度限制统一成易积分的范围","pitfall":"直接用整圆或整卦限角度，忽略真实交界"},"volume_unknown":{"family":"volume","route":"把未知三重积分设为常数，再对原方程积分求解","gate":"同一个未知积分在方程右侧是否与积分变量无关","why":"将整体积分设常数可得到一元代数方程，再回代求函数","pitfall":"把未知积分当作随 x,y,z 改变的普通函数"},"volume_slice":{"family":"volume","route":"固定一个坐标，用截面积把三重积分化为单积分","gate":"固定高度处截面面积是否已正确求出","why":"先对横截面积分，再对高度积分体现累次积分的本质","pitfall":"遗漏截面面积随高度的变化"},"volume_centroid":{"family":"volume","route":"先求各高度的截面积及其形心，再计算总体一阶矩","gate":"切片中心是否随高度移动","why":"形心由一阶矩除以体积；斜截面中心不能都按坐标零处理","pitfall":"只算截面面积，却把所有截面的中心都当原点"},"vector_div":{"family":"vector","route":"分别求三个对应坐标的偏导，再把结果相加","gate":"散度是标量，各分量应对相应坐标求导","why":"散度等于三个对应偏导之和，不能做向量叉乘","pitfall":"错把散度算成三分量向量"},"vector_curl":{"family":"vector","route":"按旋度分量公式逐项计算三个偏导差","gate":"旋度结果是向量，分量次序和正负号要明确","why":"旋度来自向量场的交叉偏导差，描述局部旋转","pitfall":"把旋度当一个标量，或调换偏导相减顺序"},"work_optim":{"family":"line","route":"先识别做功微分式是否为全微分，再将终点约束转为最值","gate":"积分微分式能否凑成一个显式势函数的全微分","why":"可积势函数使路径做功只依赖终点，剩余变为约束最优化","pitfall":"尚未证实路径无关就直接只用终点坐标"}};
