 const typeLabels={"line1":"第一类曲线积分：标量沿弧长累加","line2":"第二类曲线积分：按方向沿路径积分","surface1":"第一类曲面积分：标量沿面积累加","surface2":"第二类曲面积分：有向通量","volume":"三重积分：对体积区域积分","divergence":"散度：向量场求标量","curl":"旋度：向量场求向量","grad":"梯度：标量场求方向向量","work":"变力做功：力场沿有向路径积分","centroid":"实体形心：体积与一阶矩","surface_mass":"薄壳质量或重心：曲面密度积分"};
