   const possible=selectedStages.length,score=high*20+other*8;
   app.innerHTML=`<div class="practice-shell arena-finish"><div class="game-topline"><a href="#/practice" class="text-link">${svg('back')} 返回训练</a><span>本题结果</span></div><div class="game-card"><div class="finish-orbit">${high===possible?'✦':'◇'}</div><span class="eyebrow">${esc(e.id)} · ${esc(moduleTitle(e.module))}</span><h1>${high===possible?'关键判断全部通过':'已完成本题方法训练'}</h1><p>${esc(e.title)}</p><div class="finish-summary"><strong>${high} / ${possible}</strong><span>最佳判断</span><strong>${score}</strong><span>本轮 XP</span></div><div class="finish-trail">${selectedStages.map((p,i)=>`<div class="finish-trail-item"><span class="${game.answers[i]==='best'?'pass':game.answers[i]==='alternative'?'partial':'miss'}">${game.answers[i]==='best'?'✓':game.answers[i]==='alternative'?'≈':'!'}</span><b>${phaseNames[p]}</b></div>`).join('')}</div><div class="finish-specific"><b>推荐通法</b><p>${esc(conceptBank[routeOf[e.id]].route)}</p><b>本质依据</b><p>${esc(conceptBank[routeOf[e.id]].why)}</p></div><div class="finish-actions"><a class="btn btn-primary" href="#/problem/${e.id}">查看完整正规解析 ${svg('arrow')}</a><button class="btn btn-outline" id="game-next">继续下一题 →</button><button class="btn btn-quiet" id="game-again">再练本题</button></div></div></div>`;
