 function nodeDown(e){if(e.target.closest('[data-expand]'))return;if(e.button!==0)return;e.stopPropagation();const el=e.currentTarget,id=el.dataset.nodeId;let n=allGraph().find(x=>x.id===id);if(!n)return;moveNode={id,el,ox:n.x,oy:n.y,px:e.clientX,py:e.clientY,moved:false};nodeStart={x:n.x,y:n.y};el.setPointerCapture(e.pointerId);el.addEventListener('pointermove',nodeMove);el.addEventListener('pointerup',nodeUp);el.addEventListener('pointercancel',nodeUp);}
