 function onPointerDown(e){if(e.button!==0)return;stage.setPointerCapture(e.pointerId);ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY});if(ptrs.size===1){gesture={type:'pan',x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y};stage.classList.add('panning')}else if(ptrs.size===2){const pts=[...ptrs.values()],mid={x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2},rect=stage.getBoundingClientRect();gesture={type:'pinch',dist:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y),z:camera.z,worldX:(mid.x-rect.left-camera.x)/camera.z,worldY:(mid.y-rect.top-camera.y)/camera.z}}}
